package dev.underthebedrock;
import dev.underthebedrock.command.*;import dev.underthebedrock.horror.*;import dev.underthebedrock.integration.IntegrationManager;import dev.underthebedrock.world.VoidWorldManager;import dev.underthebedrock.world.StructureManager;import dev.underthebedrock.world.SupplyDropManager;import dev.underthebedrock.item.CustomItemManager;import org.bukkit.command.PluginCommand;import org.bukkit.plugin.java.JavaPlugin;import java.util.Objects;
public final class UnderTheBedrockPlugin extends JavaPlugin {
 private VoidWorldManager worlds;private IntegrationManager integrations;private OccurrenceDirector occurrences;private HorrorEntityController entities;private ClueManager clues;private StructureManager structures;private SupplyDropManager supplyDrops;private CustomItemManager customItems;private LoreManager lore;private CivilizationManager civilization;private WorldEntryListener worldEntry;private HorrorEventDirector horrorEvents;private FacilityManager facilities;
 @Override public void onEnable(){saveDefaultConfig();integrations=new IntegrationManager(this);if(!integrations.initialize()){getServer().getPluginManager().disablePlugin(this);return;}worlds=new VoidWorldManager(this);PlayerHorrorMemoryStore memoryStore=new PlayerHorrorMemoryStore(this);occurrences=new OccurrenceDirector(this,worlds,memoryStore);entities=new HorrorEntityController(this,worlds,occurrences,integrations.betterModel());clues=new ClueManager(this,worlds,occurrences);customItems=new CustomItemManager(this,worlds);structures=new StructureManager(this,worlds);supplyDrops=new SupplyDropManager(this,worlds);lore=new LoreManager(this);lore.start();civilization=new CivilizationManager(this);worldEntry=new WorldEntryListener(this,worlds,customItems);getServer().getPluginManager().registerEvents(worldEntry,this);worldEntry.start();facilities=new FacilityManager(this);facilities.start();if(getConfig().getBoolean("horror.civilization.enabled",true))civilization.start();
  if(getConfig().getBoolean("horror.director.enabled",true)){occurrences.start();if(getConfig().getBoolean("horror.entities.enabled",true))entities.start();if(getConfig().getBoolean("horror.clues.enabled",true))clues.start();}
  horrorEvents=new HorrorEventDirector(this);if(getConfig().getBoolean("horror.events.enabled",true))horrorEvents.start();
  if(getConfig().getBoolean("horror.items.enabled",true))customItems.start();register("enter",new EnterCommand(worldEntry));register("underthebedrock",new UnderTheBedrockCommand(worlds,integrations,worldEntry));register("evidence",new EvidenceCommand(occurrences));
  if(getConfig().getBoolean("horror.structures.enabled",true))structures.start();if(getConfig().getBoolean("horror.supply-drops.enabled",true))supplyDrops.start();
  if(getConfig().getBoolean("world.auto-start",true)||getConfig().getBoolean("world.enabled-on-startup",false)){if(worlds.start())getServer().getScheduler().runTask(this,worldEntry::routeOnlinePlayers);else getLogger().severe("Could not initialize the configured horror world.");}
  getLogger().info("Under The Bedrock enabled; auto-start="+worlds.isActive()+", world lockdown="+getConfig().getBoolean("world.lock-to-experience",true)+".");}
 @Override public void onDisable(){if(worldEntry!=null)worldEntry.stop();if(facilities!=null)facilities.stop();if(horrorEvents!=null)horrorEvents.stop();if(civilization!=null)civilization.stop();if(customItems!=null)customItems.stop();if(supplyDrops!=null)supplyDrops.stop();if(structures!=null)structures.stop();if(clues!=null)clues.stop();if(entities!=null)entities.stop();if(occurrences!=null)occurrences.stop();}
 public OccurrenceDirector getOccurrenceDirector(){return occurrences;}public CustomItemManager getCustomItems(){return customItems;}public LoreManager getLoreManager(){return lore;}public VoidWorldManager getWorlds(){return worlds;}public FacilityManager getFacilityManager(){return facilities;}
 private void register(String name,org.bukkit.command.CommandExecutor executor){PluginCommand c=Objects.requireNonNull(getCommand(name),"Missing command: "+name);c.setExecutor(executor);if(executor instanceof org.bukkit.command.TabCompleter tabs)c.setTabCompleter(tabs);}
}
